float t_max = FAR;


geometry trace(vec3 o, vec3 d, int maxI) {

    float omega = 1.3;
    float t = .01;
    float candidate_error = INFINITY;
    float candidate_t = t;
    float previousRadius = 0.;
    float stepLength = 0.;
    float pixelRadius = //tan(radians (FOV) / 2.0) 
        1. / 450.;
    float functionSign = map(o).dist < 0. ? -1. : +1.;
    geometry mp;

    for (int i = 0; i < maxI; ++i) {
        //if (maxI > 0 && i > maxI) break; 
        mp = map(d * t + o);
        float signedRadius = functionSign * mp.dist;
        float radius = abs(signedRadius);
        bool sorFail = omega > 1. &&
        (radius + previousRadius) < stepLength;
        if (sorFail) {
            stepLength -= omega * stepLength;
            omega = 1.;
        } else {
        stepLength = signedRadius * omega * 1.;
        }
        previousRadius = radius;
        float error = radius / t;
        if (!sorFail && error < candidate_error) {
            candidate_t = t;
            candidate_error = error;
        }
        if (!sorFail && error < pixelRadius || t > t_max) break;
        t += stepLength;
   	}

    mp.dist = candidate_t;

    if ((t > t_max || candidate_error > pixelRadius)) mp.dist = INFINITY;    

    return mp;
}


float softShadow(vec3 ro, vec3 lp, float k) {
    const int maxIterationsShad = 15;
    vec3 rd = (lp - ro); // Unnormalized direction ray.

    float shade = 1.;
    float dist = .05;
    float end = max(length(rd), .01);
    float stepDist = end / float(maxIterationsShad);

    rd /= end;
    for (int i = 0; i < maxIterationsShad; i++) {
        float h = map(ro + rd * dist).dist;
        //shade = min(shade, k*h/dist);
        shade = min(shade, smoothstep(0.0, 1.0, k * h / dist)); 
        dist += min(h, stepDist * 2.); 
        if (h < 0.001 || dist > end) break;
    }
    return min(max(shade, 0.0), 1.0);
}


//	normal calculation
vec3 normal(vec3 pos) {
    float eps=.1, d = map(pos).dist;
	return normalize(vec3(map(pos+vec3(eps,0,0)).dist-d,map(pos+vec3(0,eps,0)).dist-d,map(pos+vec3(0,0,eps)).dist-d));
}

float getAO(vec3 hitp, vec3 normal, float dist)
{
    return clamp(map(hitp + normal * dist).dist / dist, .3, 1.);
}

vec3 clouds(vec3 rd, vec3 ro) {
    vec2 uv = rd.xz / rd.y;

    pR(uv, B(uv.xxy * .1));
    vec3 clouds = vec3(
        B(
            vec3(
                uv + vec2(0., ro.z  * .05), 9.
            )
        ) * 4.

    );
 	clouds = pow(clouds, vec3(1.)) + vec3(sin(uv.y) / 2. + .5, .5, 1.);
    return clouds * max(0., min(rd.y / 2., .1));
}


vec3 Sky(in vec3 rd, bool showSun, vec3 lightDir, vec3 ro)
{

    float sunSize = 0.;
    float sunAmount = max(dot(rd, lightDir), 0.4);
    float v = pow(1. - max(rd.y, 0.0), 1.1);
    vec3 cl = vec3(1.);
    vec3 sky = mix(cl, vec3(.3, .2, .0), v);

    sky += lightColour * sunAmount * sunAmount * 1. + lightColour * min(pow(sunAmount, 122.0)* sunSize, 1.2 * sunSize);
    return clamp(sky, 0.3, 1.0) + clouds(rd, ro);;
}

vec3 doColor( in vec3 sp, in vec3 rd, in vec3 sn, in vec3 lp, inout geometry obj) {
	vec3 sceneCol = obj.color;
    lp = sp + lp;
    vec3 ld = lp - sp; // Light direction vector.
    float lDist = max(length(ld / 2.), 0.01); // Light to surface distance.
    ld /= lDist; // Normalizing the light vector.

    // Attenuating the light, based on distance.
    float atten = 1. / (1.0 + lDist * 0.025 + lDist * lDist * 0.5);

    // Standard diffuse term.
    float diff = max(dot(sn, ld), obj.diffuse);
    // Standard specualr term.
    float spec = max(dot(reflect(-ld, sn), -rd), obj.specular);


    // Coloring the object. You could set it to a single color, to
    // make things simpler, if you wanted.
    obj.color += floor(B(iTime + reps * 20.) * 2.);//getObjectColor(sp, sn, obj);
	obj.color = obj.color  * (diff + .15) * spec * .1 ;
    // Combining the above terms to produce the final scene color.
    //sceneCol += ();// * atten;

    // Return the color. Done once every pass... of which there are
    // only two, in this particular instance.
    if (sp.y < -8.) obj.color += floor(sin(length(obj.orgSpace.xz))) * 4.;// * 1.3 / (atan(obj.orgSpace.x, obj.orgSpace.z)))) * 4.2 ;
    return obj.color;
}

